import{_ as l,a0 as p,w as d,s as r,ao as a,I as o,x as i,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"我如何在 Linux 上把 Vim 配置為默認編輯器 | LCTT x X-CMD","titleTemplate":false,"description":"我如何在 Linux 上把 Vim 配置為默認編輯器 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我如何在 Linux 上把 Vim 配置為默認編輯器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我如何在 Linux 上把 Vim 配置為默認編輯器 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220214 How I configure Vim as my default editor on Linux","title":"我如何在 Linux 上把 Vim 配置為默認編輯器","tag":"202204","desc":""},"relativePath":"202204/20220214 How I configure Vim as my default editor on Linux.md","filePath":"[post].md"}'),u={name:"202204/20220214 How I configure Vim as my default editor on Linux.md"};function m(c,e,h,f,g,b){const s=p("Link");return d(),r("div",null,[e[23]||(e[23]=a('<h1 id="我如何在-linux-上把-vim-配置為默認編輯器" tabindex="-1">我如何在 Linux 上把 Vim 配置為默認編輯器 <a class="header-anchor" href="#我如何在-linux-上把-vim-配置為默認編輯器" aria-label="Permalink to “我如何在 Linux 上把 Vim 配置為默認編輯器”">​</a></h1><blockquote><p>Vim 是我最喜愛的編輯器。對於那些默認使用其他編輯器的程序，我對系統所做的這些改變可以使得 Vim 成為它們默認編輯器。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202204/15/172912fvtvpfff83r373yy.png" alt=""></p><p>我使用 Linux 大概有 25 年了，在那之前我還使用了幾年的 Unix。在這段時間裏，我對一些日常使用的工具形成了偏好。Vim 是我使用的最重要的工具之一。</p><p>我在 90 年代初學習 Solaris 時，就開始使用 Vi 了，因為有人告訴我，它在任何系統上都能使用。從我的經驗來看，確實是這樣。我也試過其他編輯器，它們都能夠勝任工作。但是，對於我來説，Vim 的使用效果最好。我經常使用它，以至於形成了肌肉記憶，甚至我在使用其他編輯器時也會下意識地去按 Vim 的快捷鍵。</p><p>另外，我只是單純地喜歡 Vim 而已。</p><p>許多配置文件使用的名字是 Vi 而不是 Vim，你可以運行 <code>vi</code> 命令。不過，<code>vi</code> 命令其實是 <code>vim</code> 命令的一個鏈接。</p>',7)),o("p",null,[e[2]||(e[2]=i("許多 Linux 工具使用的編輯器都是在模擬或是直接調用的 ",-1)),t(s,{href:"https://opensource.com/article/20/12/gnu-nano"},{default:n(()=>[...e[0]||(e[0]=[i("Nano",-1)])]),_:1}),e[3]||(e[3]=i("、",-1)),t(s,{href:"https://opensource.com/tags/emacs"},{default:n(()=>[...e[1]||(e[1]=[i("Emacs",-1)])]),_:1}),e[4]||(e[4]=i(" 或者 Vim。其他的一些工具允許用户（比如那些有着明確偏好的用户）使用他們喜歡的編輯器。舉兩個對我影響最大的例子，一個是 Bash 命令列，它默認使用 Emacs；另一個是 Alpine 文本模式的郵件客户端，它默認使用 Pico。事實上，Pico 是專門為 Pine 郵件客户端編寫的，而 Pine 是 Alpine 的前身。",-1))]),e[24]||(e[24]=a(`<p>並非所有使用外部編輯器的程序都是可配置的。有些程序只使用開發者指定的編輯器。對於那些可配置的應用程序，有不同的方法來選擇你喜歡的編輯器。</p><h3 id="在-linux-命令列中編輯" tabindex="-1">在 Linux 命令列中編輯 <a class="header-anchor" href="#在-linux-命令列中編輯" aria-label="Permalink to “在 Linux 命令列中編輯”">​</a></h3><p>除了實際編輯文本文件外，另一個我經常使用，且和編輯密切相關的工具是 Bash shell。Bash 的默認編輯器是 Emacs。雖然我也用過 Emacs，但我肯定更喜歡 Vim。所以很多年前，我把 Bash 命令列的默認編輯器從 Emacs 換成了 Vim，這對我來説更舒服。</p><p>有很多種方法可以配置 Bash。你可以使用一個本地配置文件，比如 <code>/home/yourhomedirectory/.bashrc</code>，它只對你的用户賬户進行默認修改，而不對同一系統的其他用户進行修改。我個人傾向於讓這些改變成為全局性的，基本上就是我的個人賬户和 root。如果你也想全局配置，你可以創建你自己的配置文件，並把它放在 <code>/etc/profile.d</code> 目錄中。</p><p>我在 <code>/etc/profile.d</code> 中添加了一個名為 <code>myBashConfig.sh</code> 的文件。<code>/etc/profile.d</code> 目錄中存放了所有已安裝的 shell 的啓動文件。在啓動終端會話時，每個 shell 僅會根據文件名的擴展名，讀取為其準備的啓動文件。例如，Bash shell 只讀取擴展名為 <code>.sh</code> 的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;截斷&gt;</span></span>
<span class="line"><span>alias vim=&#39;vim -c &quot;colorscheme desert&quot; &#39;</span></span>
<span class="line"><span># 把 vi 設置為 Bash 的默認編輯器</span></span>
<span class="line"><span>set -o vi</span></span>
<span class="line"><span># 為所有檢查 $EDITOR 變量的程序設置默認編輯器為 vi</span></span>
<span class="line"><span>EDITOR=vi</span></span>
<span class="line"><span>&lt;截斷&gt;</span></span></code></pre></div><p>在這個全局 Bash 配置文件段中，<code>set -o vi</code> 將 Vi 設置為默認編輯器。這個 <code>set</code> 命令中的 <code>-o</code> 選項將 <code>vi</code> 定義為編輯器。為使配置生效，你需要關閉所有正在運行的 Bash 會話，並打開新的會話。</p><p>現在，你現在可以使用所有你熟悉的 Vim 命令，包括光標移動。只要按下 <code>Esc</code> 鍵就可以進入 Vim 編輯模式。我特別喜歡多次使用 <code>b</code> 將光標移回多個字的功能。</p><h3 id="將-vim-設置為其他程序的默認值" tabindex="-1">將 Vim 設置為其他程序的默認值 <a class="header-anchor" href="#將-vim-設置為其他程序的默認值" aria-label="Permalink to “將 Vim 設置為其他程序的默認值”">​</a></h3><p>一些 Linux 命令列工具和程序會檢查 <code>$EDITOR</code> 環境變量來決定使用哪個編輯器。你可以用下面的命令檢查這個變量的當前值。我在一個新安裝的虛擬機上運行過該命令，以查看默認的編輯器到底是什麼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo $EDITOR</span></span>
<span class="line"><span>/usr/bin/nano</span></span>
<span class="line"><span>#</span></span></code></pre></div><p>默認情況下，檢查 <code>$EDITOR</code> 環境變量的 Fedora 程序會使用 Nano 編輯器。在 <code>myBashConfig.sh</code> 中添加一行 <code>EDITOR=vi</code>（如上面的片段所示），可以將默認值改為 Vi（Vim）編輯器。然而，不是所有使用外部編輯器的命令列程序都會檢查這個環境變量。</p><h3 id="在-alpine-中編輯電子郵件" tabindex="-1">在 Alpine 中編輯電子郵件 <a class="header-anchor" href="#在-alpine-中編輯電子郵件" aria-label="Permalink to “在 Alpine 中編輯電子郵件”">​</a></h3>`,13)),o("p",null,[e[6]||(e[6]=i("幾周前，我認為 Pico 不太適合作為我的電子郵件編輯器。我可以使用它，而且在從 Thunderbird 轉到 ",-1)),t(s,{href:"https://opensource.com/article/21/5/alpine-linux-email"},{default:n(()=>[...e[5]||(e[5]=[i("Alpine",-1)])]),_:1}),e[7]||(e[7]=i(" 之後的一段時間內我也用了一段時間。但我發現，Pico 妨礙了我，我總是習慣使用 Vim 按鍵序列，這影響了我的工作效率。",-1))]),e[25]||(e[25]=a('<p>我在 Alpine 的用户幫助中看到，默認編輯器是可以修改的。我決定把它改成 Vim。實際上這很容易做到。</p><p>在 Alpine 主菜單上，按 <code>S</code> 鍵進入設置，然後按 <code>C</code> 鍵進行配置。在 “<ruby>編輯器設置<rt>Composer Preferences</rt></ruby>” 部分，按 <code>X</code> 選擇 “<ruby>啓用外部編輯器命令<rt>Enable Alternate Editor Command</rt></ruby>” 和 “<ruby>隱式啓用外部編輯器<rt>Enable Alternate Editor Implicitly</rt></ruby>” 項目。在往下滾動幾頁的 “<ruby>高級用户設置<rt>Advanced User Preferences</rt></ruby>” 部分，找到 `Editor 那一行。如果它還沒有被修改的話，它應該是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Editor    = &lt;No Value Set&gt;</span></span></code></pre></div><p>用光標欄突出顯示 <code>Editor</code> 這一行，然後按回車鍵來編輯。將 <code>&lt;No Value Set&gt;</code> 改為 <code>vim</code>，再按回車鍵，然後按 <code>E</code> 鍵退出，最後按 <code>Y</code> 鍵保存修改。</p><p>要用 Vim 編輯電子郵件，只需進入電子郵件正文，Vim 就會自動啓動，就像 Pico 那樣。所有我喜歡的編輯功能都還在，因為它實際上是在使用 Vim。甚至退出 Vim 的 <code>Esc :wq</code> 序列也是一樣的。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>與其他編輯器相比，我更喜歡 Vim，對我的系統進行的這些改動後，那些默認使用其他編輯器的應用程序，將使用 Vim 來替代它們的默認編輯器。有些程序使用 <code>$EDITOR</code> 環境變量，因此你只需要做一次修改就夠了。其他有用户配置選項的程序，如 Alpine，則必須為每個程序單獨設置。</p><p>這種可以選擇你喜歡的外部編輯器的能力，非常符合 Unix 哲學的宗旨：“每個程序都只做一件事，而且要做得出色”。既然已經有幾個優秀的編輯器，為什麼還要再寫一個呢？而且它也符合 Linux 哲學的宗旨：“使用你最喜歡的編輯器”。</p><p>當然，你可以把你的默認文本編輯器改為 Nano、Pico、Emacs 或任何其他你喜歡的編輯器。</p><hr>',10)),o("p",null,[e[9]||(e[9]=i("via: ",-1)),t(s,{href:"https://opensource.com/article/22/2/configure-vim-default-editor"},{default:n(()=>[...e[8]||(e[8]=[i("https://opensource.com/article/22/2/configure-vim-default-editor",-1)])]),_:1})]),o("p",null,[e[14]||(e[14]=i("作者：",-1)),t(s,{href:"https://opensource.com/users/dboth"},{default:n(()=>[...e[10]||(e[10]=[i("David Both",-1)])]),_:1}),e[15]||(e[15]=i(" 選題：",-1)),t(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[11]||(e[11]=[i("lujun9972",-1)])]),_:1}),e[16]||(e[16]=i(" 譯者：",-1)),t(s,{href:"https://github.com/lkxed"},{default:n(()=>[...e[12]||(e[12]=[i("lkxed",-1)])]),_:1}),e[17]||(e[17]=i(" 校對：",-1)),t(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[13]||(e[13]=[i("wxy",-1)])]),_:1})]),o("p",null,[e[20]||(e[20]=i("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[18]||(e[18]=[i("LCTT",-1)])]),_:1}),e[21]||(e[21]=i(" 原創編譯，",-1)),t(s,{href:"https://linux.cn/"},{default:n(()=>[...e[19]||(e[19]=[i("Linux中國",-1)])]),_:1}),e[22]||(e[22]=i(" 榮譽推出",-1))])])}const k=l(u,[["render",m]]);export{T as __pageData,k as default};
